package basics1;

public class PracticalSessions {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		
		System.out.println("Welcome to core java session");
		
		System.out.println("\n Automation \n");
		
		int a=5,b=6; //initialization
		int c,d; //declaration
		
		//int is a datatype used for integer values, max digit limit:9
		System.out.println("Addition "+(a+b));
		//                  Addition     11
		
		System.out.println("Subtraction "+(a-b));
		//+ operator is called concat
		
		System.out.println("Multiplication is "+(a*b));
		
		System.out.println("Divison is "+(a/b));
		
		
		//double is data type used for decimal values 
		
		System.out.println("--Arithmetic Operation using double operation---\n");
		double f=4.5, e=5.5;
		
		System.out.println("Addition is "+(f+e));
		System.out.println("Subtraction is "+(f-e));
		System.out.println("Mul is " + (f*e));
		System.out.println("Div is "+(f/e));
		
		//float is a data type used for decimal values 
		
		System.out.println("--Arithmetic operation using float---\n");
		//145.667
		float k=8.7f, m=5.6f;
		
		System.out.println("Addition is " +(k+m));
		System.out.println("Subtraction is "+(k-m));
		System.out.println("Mul is "+(k*m));
		System.out.println("Div is "+(k/m));
		
		

	}

}
